import { useState } from "react";

/* ─── Design tokens ─────────────────────────────────────── */
const C = {
  black:    "#0a0a0a",
  white:    "#fafaf8",
  cream:    "#f5f0e8",
  gold:     "#c9a84c",
  goldDk:   "#8a6f2e",
  goldLt:   "rgba(201,168,76,.15)",
  gray100:  "#f0ede8",
  gray200:  "#e0dbd2",
  gray400:  "#9b9690",
  gray600:  "#5a5650",
  red:      "#c0392b",
  green:    "#27ae60",
  blue:     "#2980b9",
};

/* ─── Shared style helpers ──────────────────────────────── */
const input = (focused, error) => ({
  width: "100%",
  height: "48px",
  padding: "0 16px",
  border: `1.5px solid ${error ? C.red : focused ? C.gold : C.gray200}`,
  borderRadius: "8px",
  fontFamily: "inherit",
  fontSize: "15px",
  color: C.black,
  background: C.white,
  outline: "none",
  boxSizing: "border-box",
  boxShadow: focused && !error ? "0 0 0 4px rgba(201,168,76,.12)" : "none",
  transition: "all .2s",
});

/* ─── OTP Input Component ───────────────────────────────── */
function OTPBox({ value, onChange }) {
  const digits = (value + "      ").slice(0, 6).split("");

  const handleInput = (e, i) => {
    const v = e.target.value.replace(/\D/g, "").slice(-1);
    const arr = [...digits];
    arr[i] = v;
    onChange(arr.join("").trim());
    if (v && i < 5) document.getElementById(`otp-${i + 1}`)?.focus();
  };

  const handleKey = (e, i) => {
    if (e.key === "Backspace" && !digits[i] && i > 0) {
      document.getElementById(`otp-${i - 1}`)?.focus();
    }
  };

  const handlePaste = (e) => {
    e.preventDefault();
    const txt = e.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
    onChange(txt);
    document.getElementById(`otp-${Math.min(txt.length, 5)}`)?.focus();
  };

  return (
    <div style={{ display: "flex", gap: "10px", justifyContent: "center", margin: "22px 0" }}>
      {digits.map((d, i) => (
        <input
          key={i}
          id={`otp-${i}`}
          type="text"
          inputMode="numeric"
          maxLength={1}
          value={d.trim()}
          onChange={(e) => handleInput(e, i)}
          onKeyDown={(e) => handleKey(e, i)}
          onPaste={handlePaste}
          style={{
            width: "50px", height: "54px",
            textAlign: "center",
            fontFamily: "monospace",
            fontSize: "22px", fontWeight: "700",
            border: `2px solid ${d.trim() ? C.gold : C.gray200}`,
            borderRadius: "8px",
            outline: "none",
            background: C.white,
            boxShadow: d.trim() ? "0 0 0 3px rgba(201,168,76,.15)" : "none",
            transition: "all .2s",
          }}
        />
      ))}
    </div>
  );
}

/* ─── Main Login Component ──────────────────────────────── */
export default function Login() {
  /* form state */
  const [identifier, setIdentifier] = useState("");
  const [password,   setPassword]   = useState("");
  const [showPw,     setShowPw]     = useState(false);
  const [remember,   setRemember]   = useState(true);

  /* OTP state */
  const [showOTP,  setShowOTP]  = useState(false);
  const [otp,      setOtp]      = useState("");
  const [timer,    setTimer]    = useState(0);

  /* UI state */
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState("");

  /* focus state for inputs */
  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);

  /* ── countdown helper ── */
  const startTimer = () => {
    setTimer(30);
    const iv = setInterval(() =>
      setTimer(t => { if (t <= 1) { clearInterval(iv); return 0; } return t - 1; }),
    1000);
  };

  /* ── submit login ── */
  const handleLogin = () => {
    setError("");
    if (!identifier.trim()) { setError("Please enter your email or phone number."); return; }
    if (!password)           { setError("Please enter your password."); return; }

    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      const isPhone = /^\d{10}$/.test(identifier.replace(/\s/g, ""));
      if (isPhone) {
        setShowOTP(true);
        startTimer();
      } else {
        /* TODO: call POST /api/v1/auth/login then redirect */
        window.location.href = "/";
      }
    }, 1200);
  };

  /* ── verify OTP ── */
  const handleVerify = () => {
    if (otp.replace(/\s/g, "").length < 6) { setError("Enter all 6 digits."); return; }
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      window.location.href = "/";
    }, 1000);
  };

  /* ── social auth ── */
  const socialAuth = (provider) => {
    alert(`Connecting to ${provider}… (integrate OAuth here)`);
  };

  /* ─────────────────── RENDER ────────────────────────────── */
  return (
    <div style={{ minHeight: "100vh", display: "flex", fontFamily: "'Segoe UI', DM Sans, sans-serif", background: C.white }}>

      {/* ════ LEFT – brand panel ════ */}
      <div style={{
        flex: 1,
        background: C.black,
        display: "flex", flexDirection: "column", justifyContent: "space-between",
        padding: "48px",
        position: "relative", overflow: "hidden",
      }}>
        {/* glow */}
        <div style={{
          position: "absolute", inset: 0, pointerEvents: "none",
          background: "radial-gradient(ellipse at 20% 80%,rgba(201,168,76,.20) 0%,transparent 55%), radial-gradient(ellipse at 80% 20%,rgba(201,168,76,.10) 0%,transparent 50%)",
        }} />

        <div style={{ position: "relative", zIndex: 1 }}>
          {/* logo */}
          <a href="/" style={{
            fontFamily: "Georgia, serif", fontSize: "28px", fontWeight: 900,
            color: "#fff", textDecoration: "none", display: "block", marginBottom: "60px",
          }}>
            The<span style={{ color: C.gold }}>Zuro</span>
          </a>

          {/* tagline */}
          <h2 style={{
            fontFamily: "Georgia, serif",
            fontSize: "clamp(26px, 3vw, 46px)",
            fontWeight: 700, color: "#fff", lineHeight: 1.1, marginBottom: "14px",
          }}>
            Welcome to{" "}
            <span style={{ color: C.gold }}>TheZuro</span>
          </h2>
          <p style={{ fontSize: "15px", color: "rgba(255,255,255,.5)", lineHeight: 1.65, maxWidth: "360px", marginBottom: "44px" }}>
            Join millions of shoppers discovering the best deals from India's top sellers.
          </p>

          {/* features */}
          {[
            ["🛍", "50,000+ products across every category"],
            ["🚀", "Free delivery on orders above ₹499"],
            ["🔒", "100% secure payments & easy returns"],
            ["⭐", "Exclusive member-only deals & cashback"],
          ].map(([icon, text]) => (
            <div key={text} style={{ display: "flex", alignItems: "center", gap: "12px", marginBottom: "14px" }}>
              <div style={{
                width: "36px", height: "36px", borderRadius: "50%", flexShrink: 0,
                background: "rgba(201,168,76,.15)", border: "1px solid rgba(201,168,76,.3)",
                display: "flex", alignItems: "center", justifyContent: "center", fontSize: "16px",
              }}>{icon}</div>
              <span style={{ fontSize: "14px", color: "rgba(255,255,255,.7)" }}>{text}</span>
            </div>
          ))}
        </div>

        <div style={{ position: "relative", zIndex: 1, fontSize: "13px", color: "rgba(255,255,255,.25)" }}>
          © 2025 TheZuro. All rights reserved.
        </div>
      </div>

      {/* ════ RIGHT – form panel ════ */}
      <div style={{
        width: "520px", minWidth: "320px",
        background: C.white,
        display: "flex", alignItems: "center", justifyContent: "center",
        padding: "48px 40px",
      }}>
        <div style={{ width: "100%", maxWidth: "400px" }}>

          {/* ── TABS ── */}
          <div style={{
            display: "flex", border: `1.5px solid ${C.gray200}`,
            borderRadius: "8px", overflow: "hidden", marginBottom: "32px",
          }}>
            {["Sign In", "Create Account"].map((lbl, i) => (
              <button
                key={lbl}
                onClick={() => { if (i === 1) window.location.href = "/register"; }}
                style={{
                  flex: 1, padding: "12px",
                  fontSize: "15px", fontWeight: i === 0 ? 600 : 500,
                  cursor: "pointer", border: "none", fontFamily: "inherit",
                  background: i === 0 ? C.black : "transparent",
                  color: i === 0 ? "#fff" : C.gray400,
                }}
              >{lbl}</button>
            ))}
          </div>

          {/* ── ERROR ALERT ── */}
          {error && (
            <div style={{
              padding: "11px 14px", borderRadius: "8px", marginBottom: "14px",
              background: "#fee2e2", color: "#991b1b", border: "1px solid #fca5a5",
              fontSize: "13px", display: "flex", alignItems: "center", gap: "8px",
            }}>⚠️ {error}</div>
          )}

          {/* ═══ LOGIN FORM ═══ */}
          {!showOTP ? (
            <>
              <h1 style={{ fontFamily: "Georgia, serif", fontSize: "26px", fontWeight: 700, marginBottom: "4px" }}>
                Welcome back 👋
              </h1>
              <p style={{ fontSize: "14px", color: C.gray400, marginBottom: "24px" }}>
                Sign in to your TheZuro account
              </p>

              {/* Identifier */}
              <div style={{ marginBottom: "16px" }}>
                <label style={{ display: "block", fontSize: "13px", fontWeight: 500, color: C.gray600, marginBottom: "6px" }}>
                  Email or Phone Number
                </label>
                <input
                  style={input(focusId, false)}
                  type="text"
                  placeholder="Enter email or 10-digit phone"
                  value={identifier}
                  onChange={e => setIdentifier(e.target.value)}
                  onFocus={() => setFocusId(true)}
                  onBlur={() => setFocusId(false)}
                  onKeyDown={e => e.key === "Enter" && handleLogin()}
                />
              </div>

              {/* Password */}
              <div style={{ marginBottom: "8px" }}>
                <label style={{ display: "block", fontSize: "13px", fontWeight: 500, color: C.gray600, marginBottom: "6px" }}>
                  Password
                </label>
                <div style={{ position: "relative" }}>
                  <input
                    style={{ ...input(focusPw, false), paddingRight: "48px" }}
                    type={showPw ? "text" : "password"}
                    placeholder="Enter your password"
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                    onFocus={() => setFocusPw(true)}
                    onBlur={() => setFocusPw(false)}
                    onKeyDown={e => e.key === "Enter" && handleLogin()}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPw(!showPw)}
                    style={{
                      position: "absolute", right: "14px", top: "50%", transform: "translateY(-50%)",
                      background: "none", border: "none", cursor: "pointer",
                      fontSize: "17px", color: C.gray400, padding: 0,
                    }}
                  >{showPw ? "🙈" : "👁"}</button>
                </div>
              </div>

              {/* Remember + Forgot */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "22px" }}>
                <label style={{ display: "flex", alignItems: "center", gap: "8px", fontSize: "13px", color: C.gray600, cursor: "pointer" }}>
                  <input
                    type="checkbox" checked={remember}
                    onChange={e => setRemember(e.target.checked)}
                    style={{ accentColor: C.gold, width: "15px", height: "15px" }}
                  />
                  Remember me
                </label>
                <a
                  href="#"
                  onClick={e => { e.preventDefault(); alert("Password reset link sent to your email!"); }}
                  style={{ fontSize: "13px", color: C.gold, textDecoration: "none", fontWeight: 500 }}
                >
                  Forgot password?
                </a>
              </div>

              {/* Submit */}
              <button
                onClick={handleLogin}
                disabled={loading}
                style={{
                  width: "100%", height: "52px",
                  background: loading ? C.gray400 : C.black,
                  color: "#fff", border: "none", borderRadius: "8px",
                  fontFamily: "inherit", fontSize: "16px", fontWeight: 600,
                  cursor: loading ? "not-allowed" : "pointer",
                  transition: "all .25s",
                }}
              >
                {loading ? "⏳ Signing in…" : "Sign In →"}
              </button>

              {/* Divider */}
              <div style={{ display: "flex", alignItems: "center", gap: "12px", margin: "20px 0", color: C.gray400, fontSize: "13px" }}>
                <div style={{ flex: 1, height: "1px", background: C.gray200 }} />
                or continue with
                <div style={{ flex: 1, height: "1px", background: C.gray200 }} />
              </div>

              {/* Social buttons */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px" }}>
                {[["G", "Google"], ["📘", "Facebook"]].map(([icon, name]) => (
                  <button
                    key={name}
                    onClick={() => socialAuth(name)}
                    style={{
                      height: "48px", border: `1.5px solid ${C.gray200}`,
                      borderRadius: "8px", background: "#fff",
                      cursor: "pointer", fontFamily: "inherit",
                      fontSize: "14px", fontWeight: 500, color: C.black,
                      display: "flex", alignItems: "center", justifyContent: "center", gap: "8px",
                    }}
                  >
                    <span style={{ fontSize: "18px" }}>{icon}</span> {name}
                  </button>
                ))}
              </div>

              <p style={{ textAlign: "center", marginTop: "22px", fontSize: "14px", color: C.gray400 }}>
                New to TheZuro?{" "}
                <a href="/register" style={{ color: C.gold, textDecoration: "none", fontWeight: 500 }}>
                  Create account
                </a>
              </p>
            </>

          ) : (
            /* ═══ OTP SCREEN ═══ */
            <>
              <button
                onClick={() => { setShowOTP(false); setOtp(""); setError(""); }}
                style={{
                  background: "none", border: "none", color: C.gold,
                  fontSize: "13px", fontWeight: 500, cursor: "pointer",
                  display: "flex", alignItems: "center", gap: "4px",
                  padding: 0, marginBottom: "18px", fontFamily: "inherit",
                }}
              >← Back</button>

              <h1 style={{ fontFamily: "Georgia, serif", fontSize: "26px", fontWeight: 700, marginBottom: "4px" }}>
                Enter OTP 🔐
              </h1>
              <p style={{ fontSize: "14px", color: C.gray400, marginBottom: "4px" }}>
                6-digit code sent to <strong style={{ color: C.black }}>+91 {identifier}</strong>
              </p>

              <OTPBox value={otp} onChange={setOtp} />

              <button
                onClick={handleVerify}
                disabled={loading}
                style={{
                  width: "100%", height: "52px",
                  background: loading ? C.gray400 : C.black,
                  color: "#fff", border: "none", borderRadius: "8px",
                  fontFamily: "inherit", fontSize: "15px", fontWeight: 600,
                  cursor: loading ? "not-allowed" : "pointer",
                }}
              >
                {loading ? "⏳ Verifying…" : "Verify & Sign In →"}
              </button>

              <p style={{ textAlign: "center", marginTop: "14px", fontSize: "13px", color: C.gray400 }}>
                Didn't receive?{" "}
                {timer > 0
                  ? <span>Resend in {timer}s</span>
                  : <span
                      onClick={() => { setOtp(""); startTimer(); }}
                      style={{ color: C.gold, cursor: "pointer", fontWeight: 500 }}
                    >Resend OTP</span>
                }
              </p>
            </>
          )}

        </div>
      </div>

      {/* responsive */}
      <style>{`
        @media (max-width: 860px) {
          .login-left { display: none !important; }
        }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { margin: 0; }
      `}</style>
    </div>
  );
}
